def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
        encoded (str): A string representing the encoded information.
        original (str): A string representing the original information corresponding to the encoded string.
        message (str): A string representing the encrypted message to be decoded.

    Returns:
        str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    try:
        # Basic validation: lengths must match for encoded and original
        if len(encoded) != len(original):
            return "Failed"

        mapping = {}
        reverse = {}

        for enc_char, orig_char in zip(encoded, original):
            # Check mapping consistency
            if enc_char in mapping:
                if mapping[enc_char] != orig_char:
                    return "Failed"
            else:
                mapping[enc_char] = orig_char

            # Ensure injectivity: encoded ↦ original must be one-to-one
            if orig_char in reverse:
                if reverse[orig_char] != enc_char:
                    return "Failed"
            else:
                reverse[orig_char] = enc_char

        # Require a complete mapping of all 26 alphabet letters
        if len(mapping) != 26:
            return "Failed"

        # Decode the message
        decoded_chars = []
        for ch in message:
            if ch not in mapping:
                return "Failed"
            decoded_chars.append(mapping[ch])

        return ''.join(decoded_chars)
    except Exception:
        return "Failed"

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.

    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) is used to explore all possible transformations. The function returns the count
    of unique numbers that can be generated from the original number, including the number itself.

    Args:
        n (int): The original integer number to transform.
        rules (list of tuples): A list of transformation rules, where each rule is represented
                                as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
        int: The total count of unique numbers that can be generated.
    """
    try:
        if not isinstance(n, int):
            raise TypeError("n must be an integer")
        if not isinstance(rules, list):
            raise TypeError("rules must be a list of tuples")
    except Exception as e:
        raise ValueError(f"Invalid input: {e}")

    # Convert original number to string representation
    original_str = str(n)

    # Build a mapping from digit (as string) to a list of possible replacement digits
    rule_map = {}
    for rule in rules:
        try:
            x, y = rule
            dx, dy = str(x), str(y)
            if len(dx) != 1 or len(dy) != 1 or not dx.isdigit() or not dy.isdigit():
                continue  # skip malformed rules
            rule_map.setdefault(dx, []).append(dy)
        except Exception:
            continue  # skip malformed entries

    if not rule_map:
        return 1  # No transformations possible

    from collections import deque

    visited = set()
    queue = deque()

    # Initial state
    queue.append(original_str)
    visited.add(int(original_str))

    while queue:
        current = queue.popleft()
        for i, ch in enumerate(current):
            if ch in rule_map:
                for replacement in rule_map[ch]:
                    new_num_str = current[:i] + replacement + current[i + 1 :]
                    try:
                        new_num_int = int(new_num_str)
                    except Exception:
                        continue
                    if new_num_int not in visited:
                        visited.add(new_num_int)
                        queue.append(new_num_str)

    return len(visited)

def sort_students(student_scores):
    """
    Sorts a list of students based on their scores. The students are sorted primarily by their total score (descending),
    then by their Chinese score (descending), and finally by their student number (ascending) in case of a tie.

    Args:
        student_scores (list): A list of tuples, where each tuple consists of (student_number, total_score, Chinese_score).

    Returns:
        list: A list of tuples sorted according to the above rules.

    Raises:
        TypeError: If the input is not a list or if any element is not a tuple.
        ValueError: If any tuple does not contain exactly three numerical values.
    """
    if not isinstance(student_scores, list):
        raise TypeError("student_scores must be a list")

    for idx, item in enumerate(student_scores):
        if not isinstance(item, tuple):
            raise TypeError(f"Element at index {idx} is not a tuple")
        if len(item) != 3:
            raise ValueError(f"Tuple at index {idx} does not have exactly three elements")
        student_number, total_score, chinese_score = item
        if not all(isinstance(val, (int, float)) for val in (student_number, total_score, chinese_score)):
            raise ValueError(f"All elements in tuple at index {idx} must be numeric")

    try:
        return sorted(
            student_scores,
            key=lambda x: (-x[1], -x[2], x[0])
        )
    except Exception as e:
        raise RuntimeError(f"An error occurred during sorting: {e}") from e
